import { supabase } from '../../../services/supabase';

export interface Job {
    id: string; // The UUID
    job_id: string; // The "Sr. No" like 3543645757 from the design
    job_type: string;
    job_title: string;
    posted_by: {
        name: string;
        avatar_url?: string;
    };
    status: 'Active' | 'Suspended' | 'Assigned' | 'Pending';
    received_proposals: number;
    posted_date: string;
}

export const fetchJobs = async (): Promise<Job[]> => {
    const { data, error } = await supabase
        .from('jobs')
        .select(`
      id,
      job_id,
      job_type,
      job_title,
      posted_by:users(name, avatar_url),
      status,
      received_proposals,
      posted_date
    `);

    if (error) {
        console.error('Error fetching jobs:', error);
        return [];
    }

    // Transform or cast data as needed based on actual db schema,
    // returning directly for now assuming schema matches.
    return data as any as Job[];
};
